test("Studio allocations cover bookings and renewals, while other desks retain the default", () => {
  const dispatch = planner({default:5, studios:new Map([["orchid", 8], ["iris", 3]])});
  assert.deepEqual(dispatch(booking("first")), {status:"booked", id:"first", remaining:1});
  assert.deepEqual(dispatch(booking("next", {action:"renew", previous:"first", day:"2025-05-02"})),
    {status:"booked", id:"next", remaining:1});
  assert.deepEqual(dispatch(booking("extra", {day:"2025-05-02", units:2})),
    {status:"full", id:"extra", remaining:1});
  assert.equal(dispatch(booking("iris", {tenant:"iris", units:4})).status, "full");
  assert.equal(dispatch(booking("unlisted", {tenant:"lily", units:5})).status, "booked");
  assert.equal(dispatch(booking("unlisted-over", {tenant:"lily", units:1})).status, "full");
  assert.equal(dispatch(booking("lily-renew", {action:"renew", previous:"unlisted",
    day:"2025-05-02", units:6})).status, "full");
  assert.equal(dispatch(booking("archive", {service:"archive", units:6})).status, "full");
  assert.equal(dispatch(booking("archive-ok", {service:"archive", units:5})).status, "booked");
  assert.equal(dispatch(booking("archive-renew", {service:"archive", action:"renew",
    previous:"archive-ok", day:"2025-05-02", units:6})).status, "full");
});

